@Test
public void shouldPeekIntoTheFuture()
{
    // WHEN
    ResultCursor result = createResult( 2 );

    // THEN
    assertThat( result.peek().value( "k1" ), equalTo( value( "v1-1" ) ) );

    // WHEN
    result.next();

    // THEN
    assertThat( result.get( "k1" ), equalTo( value( "v1-1" ) ) );
    assertThat( result.peek().value( "k1" ), equalTo( value( "v1-2" ) ) );

    // WHEN
    result.next();

    // THEN
    assertThat( result.get( "k1" ), equalTo( value( "v1-2" ) ) );

    // AND THEN
    assertFalse( result.peek().hasRecord() );
}

